#include <shared_mutex>
#include <chrono>
#include <cassert>
#include <type_traits>
#include <utility>

int main() {
    std::shared_mutex mutex;
    mutex.lock();
    mutex.unlock();
    assert(mutex.try_lock());
    mutex.unlock();

    mutex.lock_shared();
    mutex.unlock_shared();
    assert(mutex.try_lock_shared());
    mutex.unlock_shared();

    // native_handle is implementation-defined and is not required for shared_mutex.
}
